/* generated by the build from dev/site-lib/reader.* and bjt/bjt.js - edit those */
// shared by the books and dhammapada sites (the builds put it in front of each site's own script):
// reading settings (theme, font size, font), share, toast, arrow keys, the top bar that hides on scroll
const themeKey = 'pitaka-theme', fontKey = 'pitaka-font-scale', fontFamilyKey = 'pitaka-font';
const storage = {
    get(key) { try { return localStorage.getItem(key); } catch (e) { return null; } },
    set(key, value) { try { localStorage.setItem(key, value); } catch (e) {} },
};
const root = document.documentElement;
// the apps before 3.0 showed the pages from file://, whose localStorage the apps hand over once (bookmarks, settings):
// added where this storage has nothing yet, then the page is shown again with them
(() => {
    const old = window.Android && window.Android.takeOldStorage ? window.Android.takeOldStorage() : window.pitakaOldStorage;
    if (!old) return;
    delete window.pitakaOldStorage;
    let added = 0;
    try { const o = JSON.parse(old); for (const k in o) if (storage.get(k) == null) { storage.set(k, o[k]); added++; } } catch (e) {}
    if (added) location.reload();
})();

function showToast(msg) {
    const toast = document.getElementById('toast');
    toast.textContent = msg;
    toast.classList.add('show');
    clearTimeout(showToast.timer);
    showToast.timer = setTimeout(() => toast.classList.remove('show'), 3000);
}

function copyText(text) {
    if (navigator.clipboard && window.isSecureContext) return navigator.clipboard.writeText(text);
    const ta = document.createElement('textarea'); // fallback for older webviews
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    const ok = document.execCommand('copy');
    ta.remove();
    return ok ? Promise.resolve() : Promise.reject();
}
function share(btn) {
    const url = btn.dataset.url, title = btn.dataset.title || document.title;
    if (navigator.share) return navigator.share({ title, url }).catch(() => {});
    copyText(url).then(() => showToast('link එක copy කර ගත්තා. ඔබට අවශ්‍ය තැන paste කරන්න.'), () => showToast(url));
}

// theme, font size and font
function updateStatusBar() { // the apps color the status bar to match the top bar
    const color = getComputedStyle(root).getPropertyValue('--surface').trim();
    if (window.Android && window.Android.setStatusBarColor) window.Android.setStatusBarColor(color);
    const ios = window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.statusBar;
    if (ios) ios.postMessage(color);
}
const currentTheme = () => root.dataset.theme || 'light';
function setTheme(theme) {
    if (theme == 'light') delete root.dataset.theme; else root.dataset.theme = theme;
    storage.set(themeKey, theme);
    updateStatusBar();
    updateSettings();
}
const currentFont = () => root.dataset.font || 'abhaya';
function setFont(font) {
    if (font == 'abhaya') delete root.dataset.font; else root.dataset.font = font;
    storage.set(fontFamilyKey, font);
    updateSettings();
}
const fontScale = () => parseFloat(getComputedStyle(root).getPropertyValue('--font-scale')) || 1;
function changeFontScale(step) {
    const scale = Math.min(1.6, Math.max(0.8, Math.round((fontScale() + step) * 10) / 10));
    root.style.setProperty('--font-scale', scale);
    storage.set(fontKey, scale);
    updateSettings();
}
function updateSettings() {
    const panel = document.getElementById('settings');
    if (!panel) return;
    panel.querySelector('output').textContent = Math.round(fontScale() * 100) + '%';
    panel.querySelectorAll('.theme-choice').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.choice == currentTheme())));
    panel.querySelectorAll('.font-choice').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.choice == currentFont())));
}
function toggleSettings(open) {
    const panel = document.getElementById('settings'), btn = document.querySelector('.settings-btn');
    if (!panel) return;
    open = open === undefined ? panel.hidden : open;
    panel.hidden = !open;
    btn.setAttribute('aria-expanded', String(open));
    if (open) { updateSettings(); appbar && appbar.classList.remove('hidden'); }
}

document.addEventListener('click', (e) => {
    const btn = e.target.closest('button');
    if (!e.target.closest('#settings, .settings-btn')) toggleSettings(false);
    if (!btn) return;
    if (btn.classList.contains('share')) share(btn);
    else if (btn.classList.contains('settings-btn')) toggleSettings();
    else if (btn.classList.contains('theme-choice')) setTheme(btn.dataset.choice);
    else if (btn.classList.contains('font-choice')) setFont(btn.dataset.choice);
    else if (btn.classList.contains('larger')) changeFontScale(0.1);
    else if (btn.classList.contains('smaller')) changeFontScale(-0.1);
});

document.addEventListener('keydown', (e) => {
    if (e.key == 'Escape') return toggleSettings(false);
    if (e.altKey || e.ctrlKey || e.metaKey || e.shiftKey || e.defaultPrevented) return;
    if (e.target.closest && e.target.closest('input, textarea, select, audio, [contenteditable]')) return;
    const a = document.querySelector({ ArrowLeft: '.pager a[rel=prev]', ArrowRight: '.pager a[rel=next]' }[e.key]);
    if (a) { e.preventDefault(); a.click(); }
});

// the top bar hides while reading down the page and comes back on scrolling up
const appbar = document.querySelector('.appbar');
if (appbar) {
    let lastY = window.scrollY;
    window.addEventListener('scroll', () => {
        const y = window.scrollY;
        if (Math.abs(y - lastY) < 8) return;
        const panel = document.getElementById('settings');
        appbar.classList.toggle('hidden', y > lastY && y > 120 && (!panel || panel.hidden));
        lastY = y;
    }, { passive: true });
}
// continue reading: the page and scroll position last read of each book (or dhammapada edition), shown on the index pages
// pages read: <body data-progress="books/kunala-jathaka" data-progress-path="kunala-jathaka/3.html" data-progress-title data-progress-label>
// index pages: <div class="continue" data-continue="books/ dhammapada/" (prefixes) or "books/kunala-jathaka" data-root="<to the pitaka.lk root>" hidden>
const progressKey = 'pitaka-progress';
const allProgress = () => { try { return JSON.parse(storage.get(progressKey) || '{}'); } catch (e) { return {}; } };
const reading = document.body.dataset.progress ? document.body.dataset : null;
if (reading) {
    const scrollable = () => document.documentElement.scrollHeight - window.innerHeight;
    const save = () => {
        const all = allProgress(), h = scrollable();
        all[reading.progress] = { path: reading.progressPath, title: reading.progressTitle, label: reading.progressLabel,
            time: Date.now(), pos: h > 0 ? Math.round(Math.min(1, Math.max(0, window.scrollY / h)) * 1000) / 1000 : 0 };
        storage.set(progressKey, JSON.stringify(all));
    };
    let timer;
    const start = () => {
        save();
        window.addEventListener('scroll', () => { clearTimeout(timer); timer = setTimeout(save, 400); }, { passive: true });
        window.addEventListener('pagehide', save);
    };
    const saved = allProgress()[reading.progress];
    if (location.hash == '#continue' && saved && saved.path == reading.progressPath) { // back to where the reader stopped
        history.replaceState(null, '', location.pathname + location.search);
        window.addEventListener('load', () => setTimeout(() => { window.scrollTo(0, saved.pos * scrollable()); start(); }, 50));
    } else start();
}
document.querySelectorAll('.continue[data-continue]').forEach(box => {
    const want = box.dataset.continue, esc = (s) => String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
    const items = Object.entries(allProgress()).filter(([k]) => want.split(' ').some(w => w.endsWith('/') ? k.startsWith(w) : k == w))
        .map(([key, v]) => ({ ...v, key })).sort((a, b) => b.time - a.time).slice(0, 3);
    if (!items.length) return;
    const close = box.querySelector('template').innerHTML;
    box.innerHTML = `<h2>නැවතුණු තැනින් කියවන්න</h2>` + items.map(v => {
        const pct = Math.round(v.pos * 100);
        return `<div class="continue-item"><a class="continue-card" href="${box.dataset.root}${esc(v.key.split('/')[0])}/${esc(v.path)}#continue"><span class="continue-title">${esc(v.title)}</span>` +
            `<span class="continue-meta">${esc(v.label)}${pct ? ` · ${pct}%` : ''}</span><span class="continue-bar"><span style="width:${Math.max(pct, 2)}%"></span></span></a>` +
            `<button type="button" class="continue-dismiss" data-key="${esc(v.key)}" aria-label="ලැයිස්තුවෙන් ඉවත් කරන්න">${close}</button></div>`;
    }).join('');
    box.hidden = false;
});
document.addEventListener('click', (e) => { // remove a book from the continue reading list
    const btn = e.target.closest('.continue-dismiss');
    if (!btn) return;
    const all = allProgress();
    delete all[btn.dataset.key];
    storage.set(progressKey, JSON.stringify(all));
    const box = btn.closest('.continue');
    btn.closest('.continue-item').remove();
    if (!box.querySelector('.continue-item')) box.hidden = true;
});

// bookmarks (the stars), shared by the sites: {key: {headings, book: {name, folder}, time, ids | path}} in localStorage
// a book page: key and href '<folder>/<ids>.html' within books/, the headings come from the table of contents (button data-ids)
// other pages (dhammapada): key and href the path from the pitaka.lk root, e.g. 'dhammapada/ss/katha-5.html' (button data-path, data-headings, data-label)
const bookmarksKey = 'books-app-bookmarks';
const bookmarks = (() => { try { return JSON.parse(storage.get(bookmarksKey) || '{}'); } catch (e) { return {}; } })();
const bookmarkKey = (btn) => btn.dataset.path || `${document.body.dataset.folder}/${btn.dataset.ids}.html`;
const bookmarkHref = (key, b, toRoot) => toRoot + (b.path ? b.path : 'books/' + key);
function bookmarkInfo(btn) {
    const d = btn.dataset;
    if (d.path) return { path: d.path, headings: JSON.parse(d.headings), book: { name: d.label, folder: d.path.split('/')[0] } };
    const headings = [];
    for (let item = btn.closest('.toc-item'); item; item = item.parentElement.closest('.toc-item')) {
        headings.unshift(item.querySelector('.toc-row > a').textContent.trim());
    }
    const main = document.querySelector('main[data-headings]'); // headings of this page come before its sub headings
    if (main && (btn.closest('.subheadings') || !headings.length)) headings.unshift(...JSON.parse(main.dataset.headings));
    return { ids: d.ids.split('-').map(Number), headings, book: { name: document.body.dataset.book, folder: document.body.dataset.folder } };
}
function toggleBookmark(btn) {
    const key = btn.dataset.key || bookmarkKey(btn);
    if (bookmarks[key]) {
        delete bookmarks[key];
        btn.classList.remove('active');
        showToast('එම මාතෘකාවේ තරුව ඉවත් කළා.');
        if (btn.closest('.bookmark-list')) btn.closest('li').remove();
    } else {
        bookmarks[key] = { ...bookmarkInfo(btn), time: Date.now() };
        btn.classList.add('active');
        showToast('තරුවක් එකතු කළා. ඒවා මුල් පිටුවේ ★ තුළ ඇත.');
    }
    storage.set(bookmarksKey, JSON.stringify(bookmarks));
}
function renderBookmarksPage(list) { // bookmarks.html, latest first
    const esc = (s) => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
    const star = document.getElementById('star-icon').innerHTML;
    const items = Object.entries(bookmarks).sort(([, a], [, b]) => b.time - a.time || a.book.name.localeCompare(b.book.name));
    list.innerHTML = items.map(([key, b]) => {
        const path = b.headings.slice(0, -1).map(esc).join(' › ');
        return `<li><a class="bm-text" href="${esc(bookmarkHref(key, b, list.dataset.root))}">${esc(b.headings[b.headings.length - 1])}
            <span class="bm-book">${esc(b.book.name)}${path ? ' › ' + path : ''} · <span class="bm-date">${new Date(b.time).toISOString().slice(0, 10)}</span></span></a>
            <button type="button" class="icon-btn star active" aria-label="තරුව ඉවත් කරන්න" data-key="${esc(key)}">${star}</button></li>`;
    }).join('\n');
    document.getElementById('no-bookmarks').hidden = items.length > 0;
}
document.querySelectorAll('button.star:not([data-key])').forEach(btn => { if (bookmarks[bookmarkKey(btn)]) btn.classList.add('active'); });
const bookmarkList = document.getElementById('bookmark-list');
if (bookmarkList) renderBookmarksPage(bookmarkList);
document.addEventListener('click', (e) => {
    const btn = e.target.closest('button.star');
    if (btn) toggleBookmark(btn);
});

updateStatusBar();

// the Buddha Jayanthi Tipitaka viewer (bjt/index.html, made by dev/bjt/build.js): the contents tree, search by title, the
// stars, and the pages of a volume at ?b=<book>&p=<printed page> - pali on the even pages, sinhala on the odd ones
(() => {
const dataEl = document.getElementById('bjt-data');
if (!dataEl) return;
const $ = (id) => document.getElementById(id);
const escHtml = (s) => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const BOOK = 0, NAME = 1, PARENT = 2, PAGE = 3; // toc entry: [book, name, parent, page, end page?]
let books, toc, children;

// stars: toc indexes, as kept by the old viewer
const starsKey = 'bjt-bookmarks';
const stars = (() => { try { return (JSON.parse(storage.get(starsKey) || '[]') || []).map(Number); } catch (e) { return []; } })();
const starred = (i) => stars.includes(i);
function toggleStar(i) {
    const at = stars.indexOf(i);
    if (at >= 0) stars.splice(at, 1); else stars.push(i);
    storage.set(starsKey, JSON.stringify(stars));
    document.querySelectorAll(`.bjt-star[data-i="${i}"]`).forEach(b => b.classList.toggle('active', at < 0));
    showToast(at < 0 ? 'තරුවක් යෙදුවා. මුල් පිටුවේ තරු යෙදූ මාතෘකා අතර ඇත.' : 'තරුව ඉවත් කළා.');
    renderStars();
}
const starButton = (i) => `<button type="button" class="icon-btn bjt-star${starred(i) ? ' active' : ''}" data-i="${i}" aria-label="තරුවක් යොදන්න">${$('star-icons').innerHTML}</button>`;

const parents = (i) => { const out = []; while ((i = toc[i][PARENT]) >= 0) out.unshift(i); return out; };
const pageHref = (b, p) => `./?b=${b}&p=${p}`;
const entryHref = (i) => pageHref(toc[i][BOOK], toc[i][PAGE]);
// a title in the search results and the stars: name, star, then the volume, page and the titles above it
const listItem = (i) => `<li><div class="toc-item"><a href="${entryHref(i)}">${escHtml(toc[i][NAME])}</a>${starButton(i)}</div>` +
    `<div class="where">${escHtml(books[toc[i][BOOK]].name)}, පිටුව ${toc[i][PAGE]}${parents(i).slice(1).map(j => ' › ' + escHtml(toc[j][NAME])).join('')}</div></li>`;

function renderStars() {
    if (!toc) return;
    const list = stars.filter(i => toc[i]);
    $('stars').hidden = !list.length;
    $('star-list').innerHTML = list.map(listItem).join('');
}

// the contents tree: the levels below the works are added when opened
function treeItem(i) {
    const kids = children[i].length ? `<button type="button" class="icon-btn toggle" aria-expanded="false" aria-label="ඇතුළත">${$('expand-icon').innerHTML}</button>` : '<span class="toggle-space"></span>';
    return `<li data-i="${i}"><div class="toc-item">${kids}<a href="${entryHref(i)}">${escHtml(toc[i][NAME])}</a><span class="page-no">${toc[i][PAGE]}</span>${starButton(i)}</div></li>`;
}
function toggleBranch(li, open) {
    const btn = li.querySelector(':scope > .toc-item > .toggle');
    open = open === undefined ? btn.getAttribute('aria-expanded') != 'true' : open;
    let ul = li.querySelector(':scope > ul');
    if (open && !ul) {
        ul = document.createElement('ul');
        ul.className = 'toc-tree';
        ul.innerHTML = children[+li.dataset.i].map(treeItem).join('');
        li.appendChild(ul);
    }
    if (ul) ul.hidden = !open;
    btn.setAttribute('aria-expanded', String(open));
}

// search by title: sinhala as typed, singlish as the sinhala spellings it may stand for (the singlish library of the
// books search); the names are compared without the joiners, which are typed or not
const plain = (s) => s.replace(/[‌‍]/g, '').toLowerCase();
let names, singlish, latest = 0;
async function search() {
    const q = plain($('q').value.trim()), scope = $('scope').value, token = ++latest;
    $('search-area').hidden = !q;
    $('contents').hidden = !!q;
    if (!q) return;
    if (q.length < 2) { $('search-status').textContent = 'අවම වශයෙන් අකුරු දෙකක් ලියන්න.'; $('results').innerHTML = ''; return; }
    let words = [q];
    if (/[a-z]/.test(q)) {
        singlish = singlish || import('/static/singlish-search/singlish.js');
        const lib = await singlish;
        const typed = q.replace(/\s+/g, ' '), loose = typed.replace(/(?<!t)t(?![th])/g, 'th').replace(/(?<!d)d(?![dh])/g, 'dh'); // 'sati' for සති (tt: ට්ඨ)
        words = [...new Set([typed, loose].flatMap(w => lib.getPossibleMatches(w, { maxMatches: 200 })).map(w => plain(w)))];
        if (token != latest) return;
    }
    names = names || toc.map(e => plain(e[NAME]));
    const found = [];
    for (let i = 0; i < toc.length && found.length < 200; i++) {
        if (scope && !parents(i).includes(+scope)) continue;
        if (words.some(w => names[i].includes(w))) found.push(i);
    }
    $('search-status').textContent = found.length ? `“${$('q').value.trim()}” ගැළපෙන මාතෘකා ${found.length >= 200 ? '200 කට වඩා' : found.length}` :
        `“${$('q').value.trim()}” ගැළපෙන මාතෘකා හමු නොවුණි. වෙනත් අකුරු වලින් උත්සාහ කරන්න.`;
    $('results').innerHTML = found.map(listItem).join('');
}

// the pages: a spread is an even (pali) page and the odd (sinhala) one after it
// wide screens show both pages unless one is chosen; phones show the side of the address (an odd page: sinhala)
const sideKey = 'bjt-side'; // 'both' or 'one' (on wide screens)
let view = null; // {b, p (even), side: 'pali' | 'sinh'}
const wide = () => window.matchMedia('(min-width: 50rem)').matches;
const imageNo = (b, p) => books[b].offset + p;
const pageExists = (b, p) => imageNo(b, p) >= 1 && imageNo(b, p) <= books[b].max;
const imageSrc = (b, p) => `newbooks/${b}/${books[b].prefix}${String(imageNo(b, p)).padStart(3, '0')}.jpg`;
// the title the page is in: the last one that starts at or before it in the volume
function entryAt(b, p) {
    let best = -1;
    for (let i = 0; i < toc.length; i++) if (toc[i][BOOK] == b && toc[i][PAGE] <= p + 1 && (best < 0 || toc[i][PAGE] >= toc[best][PAGE])) best = i;
    return best;
}
function showSides() {
    const side = wide() && storage.get(sideKey) != 'one' ? 'both' : view.side;
    $('spread').dataset.side = side;
    document.querySelectorAll('.sides button').forEach(btn => btn.setAttribute('aria-pressed', String(btn.dataset.side == side)));
}
function chooseSide(side) {
    if (wide()) storage.set(sideKey, side == 'both' ? 'both' : 'one');
    if (side != 'both') view.side = side;
    const p = view.p + (view.side == 'sinh' ? 1 : 0);
    history.replaceState(null, '', pageHref(view.b, p));
    showPages(view.b, p, false, true);
}
function showPages(b, p, push, keepScroll) {
    const even = p - (((p % 2) + 2) % 2);
    view = { b, p: even, side: p % 2 ? 'sinh' : 'pali' };
    if (push) history.pushState(null, '', pageHref(b, p));
    const book = books[b], e = entryAt(b, even);
    const figure = (pg, cls, label) => pageExists(b, pg) ? `<figure class="bjt-page ${cls}"><img src="${imageSrc(b, pg)}" alt="${escHtml(book.name)}, ${label} පිටුව ${pg}" width="1693" height="2814"><figcaption>${label} ${pg}</figcaption></figure>` : `<figure class="bjt-page ${cls} empty"></figure>`;
    $('spread').innerHTML = figure(even, 'pali', 'පාළි') + figure(even + 1, 'sinh', 'සිංහල');
    $('page-nums').textContent = `${book.name}, පිටු ${even}-${even + 1}`;
    const step = view.side == 'sinh' ? 1 : 0;
    const prev = pageExists(b, even - 2) || pageExists(b, even - 1), next = pageExists(b, even + 2) || pageExists(b, even + 3);
    document.querySelectorAll('.spread-pager .prev').forEach(a => { a.classList.toggle('off', !prev); a.href = pageHref(b, even - 2 + step); });
    document.querySelectorAll('.spread-pager .next').forEach(a => { a.classList.toggle('off', !next); a.href = pageHref(b, even + 2 + step); });
    const trail = e >= 0 ? [...parents(e), e] : [];
    $('where').innerHTML = ['<a href="./">පටුන</a>', ...trail.map(i => `<a href="${entryHref(i)}">${escHtml(toc[i][NAME])}</a>`)].join(' › ');
    const star = $('reader-star');
    star.hidden = e < 0;
    if (e >= 0) { star.dataset.i = e; star.classList.toggle('active', starred(e)); }
    const title = `${e >= 0 ? toc[e][NAME] + ' – ' : ''}${book.name} ${even}-${even + 1} | බුද්ධ ජයන්ති ත්‍රිපිටකය`;
    $('reader-share').dataset.url = `${location.origin}${location.pathname}?b=${b}&p=${even + step}`;
    $('reader-share').dataset.title = document.title = title;
    $('reader-title').textContent = title;
    $('home').hidden = true;
    $('reader').hidden = false;
    showSides();
    if (!keepScroll) window.scrollTo(0, 0);
    for (const pg of [even + 2, even + 3]) if (pageExists(b, pg)) new Image().src = imageSrc(b, pg); // the next spread, ahead
}
const homeTitle = document.title;
function showHome() {
    view = null;
    document.title = homeTitle;
    $('reader').hidden = true;
    $('home').hidden = false;
}
function route(push) {
    const params = new URLSearchParams(location.search), b = +params.get('b'), p = +params.get('p');
    if (books[b] && Number.isInteger(p) && p > -1000) showPages(b, p, push); else showHome();
}

// clicks: the tree, the stars, the sides, and the links within the viewer (no page load)
document.addEventListener('click', (ev) => {
    const btn = ev.target.closest('button');
    if (btn && btn.classList.contains('toggle')) return toggleBranch(btn.closest('li'));
    if (btn && btn.classList.contains('bjt-star')) return toggleStar(+btn.dataset.i);
    if (btn && btn.dataset.side) return view && chooseSide(btn.dataset.side);
    const a = ev.target.closest('a');
    if (!a || ev.ctrlKey || ev.metaKey || ev.shiftKey || ev.button) return;
    const url = new URL(a.href, location.href);
    if (url.pathname != location.pathname || url.origin != location.origin) return;
    ev.preventDefault();
    history.pushState(null, '', url.search ? url.search : './');
    route(false);
});
window.addEventListener('popstate', () => route(false));
window.addEventListener('resize', () => { if (view) showSides(); });

const q = $('q');
q.addEventListener('input', () => { clearTimeout(search.timer); search.timer = setTimeout(search, 200); });
q.addEventListener('focus', () => { if (view) { history.pushState(null, '', './'); showHome(); } });
$('scope').addEventListener('change', search);

fetch(dataEl.dataset.src).then(r => r.json()).then(d => {
    ({ books, toc } = d);
    children = toc.map(() => []);
    toc.forEach((e, i) => { if (e[PARENT] >= 0) children[e[PARENT]].push(i); });
    renderStars();
    route(false);
    if (q.value) search();
}).catch(() => showToast('පටුන ලබා ගැනීමට නොහැකි විය. පිටුව නැවත load කරන්න.'));
})();
